SET NAMES utf8mb4;
-- S1 additive project metadata; no role grants, no old signature/history rewriting.
SET @ddl=IF((SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='hrm_payroll_requirement_project' AND column_name='owner_id')=0,'ALTER TABLE hrm_payroll_requirement_project ADD COLUMN owner_id bigint NULL','SELECT 1');
PREPARE stmt FROM @ddl; EXECUTE stmt; DEALLOCATE PREPARE stmt;
