SET @ddl=IF((SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='hrm_payroll_requirement' AND column_name='project_scope_version')=0,'ALTER TABLE hrm_payroll_requirement ADD COLUMN project_scope_version int NULL','SELECT 1');
