CREATE TABLE IF NOT EXISTS hrm_payroll_requirement_project_grant (id bigint NOT NULL AUTO_INCREMENT PRIMARY KEY,project_id bigint NOT NULL,user_id bigint NOT NULL,actions varchar(1000) NOT NULL,ceiling_json text NULL,evidence text NOT NULL,valid_from date NOT NULL,valid_to date NOT NULL,creator varchar(64) DEFAULT '',create_time datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,updater varchar(64) DEFAULT '',update_time datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,deleted bit NOT NULL DEFAULT FALSE,tenant_id bigint NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS hrm_payroll_requirement_project_event (id bigint NOT NULL AUTO_INCREMENT PRIMARY KEY,project_id bigint NOT NULL,actor_id bigint NOT NULL,action varchar(32) NOT NULL,snapshot mediumtext NOT NULL,creator varchar(64) DEFAULT '',create_time datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,updater varchar(64) DEFAULT '',update_time datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,deleted bit NOT NULL DEFAULT FALSE,tenant_id bigint NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS hrm_payroll_requirement_template (id bigint NOT NULL AUTO_INCREMENT PRIMARY KEY,catalog_key varchar(64) NOT NULL,template_item_id varchar(64) NOT NULL,template_version int NOT NULL,original_code varchar(64) NOT NULL,description varchar(1000) NOT NULL,withdrawn bit NOT NULL DEFAULT FALSE,creator varchar(64) DEFAULT '',create_time datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,updater varchar(64) DEFAULT '',update_time datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,deleted bit NOT NULL DEFAULT FALSE,tenant_id bigint NOT NULL DEFAULT 0,UNIQUE KEY uk_template(tenant_id,catalog_key,template_item_id,template_version)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
SET @old_index=(SELECT index_name FROM information_schema.statistics WHERE table_schema=DATABASE() AND table_name='hrm_payroll_requirement' AND non_unique=0 GROUP BY index_name HAVING GROUP_CONCAT(column_name ORDER BY seq_in_index)='tenant_id,code' LIMIT 1);
SET @ddl=IF(@old_index IS NULL,'SELECT 1',CONCAT('ALTER TABLE hrm_payroll_requirement DROP INDEX `',REPLACE(@old_index,'`','``'),'`'));
PREPARE stmt FROM @ddl; EXECUTE stmt; DEALLOCATE PREPARE stmt;
SET @ddl=IF((SELECT COUNT(*) FROM information_schema.statistics WHERE table_schema=DATABASE() AND table_name='hrm_payroll_requirement' AND index_name='uk_project_code')=0,'ALTER TABLE hrm_payroll_requirement ADD UNIQUE KEY uk_project_code(tenant_id,project_id,code)','SELECT 1');
PREPARE stmt FROM @ddl; EXECUTE stmt; DEALLOCATE PREPARE stmt;
SET @ddl=IF((SELECT COUNT(*) FROM information_schema.statistics WHERE table_schema=DATABASE() AND table_name='hrm_payroll_requirement' AND index_name='uk_project_template')=0,'ALTER TABLE hrm_payroll_requirement ADD UNIQUE KEY uk_project_template(tenant_id,project_id,template_item_id)','SELECT 1');
PREPARE stmt FROM @ddl; EXECUTE stmt; DEALLOCATE PREPARE stmt;
